skip_unless_full_tests()

# Expected values are SymPy's outputs for the same calls (sympy/discrete/tests/test_convolutions.py);
# the rows come from the battery that compares this port with SymPy.

test_that("convolutions: conv matches SymPy", {
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(a, b) })), "[-247*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30 + 787/60, -sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) + 3*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 + sqrt(3)/2 + 77/4 - 17*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 - sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) + sqrt(3)*I/2 + 17*I/4, -3*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/10 + 809/60 + 9*sqrt(3), 3*sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 311*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60 + 37*sqrt(3)/8 + 2681/120 - 437*I/120 - 7*sqrt(3)*I/8 + 7*sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 437*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60, 163*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30 + 5*sqrt(3) + 279/20, sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) + 17*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 + 7*sqrt(3)/2 + 39/4 - sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) - 3*I/4 + 3*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 + sqrt(3)*I/2, 259*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30 + 277/60 + 3*sqrt(3), 67/120 + 7*sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 9*sqrt(3)/8 + 437*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60 - 311*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60 - 3*sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 3*sqrt(3)*I/8 + 311*I/120, -79/60 + 247*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution_fft(a, b) })), "[-247*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30 + 787/60, -sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) + 3*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 + sqrt(3)/2 + 77/4 - 17*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 - sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) + sqrt(3)*I/2 + 17*I/4, -3*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/10 + 809/60 + 9*sqrt(3), 3*sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 311*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60 + 37*sqrt(3)/8 + 2681/120 - 437*I/120 - 7*sqrt(3)*I/8 + 7*sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 437*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60, 163*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30 + 5*sqrt(3) + 279/20, sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) + 17*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 + 7*sqrt(3)/2 + 39/4 - sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) - 3*I/4 + 3*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 + sqrt(3)*I/2, 259*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30 + 277/60 + 3*sqrt(3), 67/120 + 7*sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 9*sqrt(3)/8 + 437*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60 - 311*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60 - 3*sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 3*sqrt(3)*I/8 + 311*I/120, -79/60 + 247*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); identical(sapply(convolution(a, b), sstr), sapply(convolution_fft(a, b), sstr)) })), "True")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(d, b, prime = q) })), "[12798, 7887, 10516, 7296, 16008, 4801, 6077, 3625, 11104]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution_ntt(b, cc, prime = p) })), "[27, 60, 67, 115, 151, 108, 87, 59, 38, 16]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(d, cc, prime = p) })), "[4266, 26826, 46765, 62391, 94779, 91723, 64568, 44416]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(b, d, dps = 5, prime = q) })), "ERR TypeError: Ambiguity in determining the type of convolution")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(a, b, dyadic = TRUE) })), "[5*sqrt(3) + 344/15, 4*sqrt(3) + 27, 9*sqrt(3) + 56/3, 5*sqrt(3) + 374/15, 19/3, 7, 14/5 + 3*sqrt(3), 2*sqrt(3) + 21/5]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(a, b, dyadic = FALSE) })), "[-247*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30 + 787/60, -sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) + 3*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 + sqrt(3)/2 + 77/4 - 17*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 - sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) + sqrt(3)*I/2 + 17*I/4, -3*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/10 + 809/60 + 9*sqrt(3), 3*sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 311*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60 + 37*sqrt(3)/8 + 2681/120 - 437*I/120 - 7*sqrt(3)*I/8 + 7*sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 437*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60, 163*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30 + 5*sqrt(3) + 279/20, sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) + 17*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 + 7*sqrt(3)/2 + 39/4 - sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2) - 3*I/4 + 3*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/2 + sqrt(3)*I/2, 259*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30 + 277/60 + 3*sqrt(3), 67/120 + 7*sqrt(6)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 9*sqrt(3)/8 + 437*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60 - 311*sqrt(2)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/60 - 3*sqrt(6)*I*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/4 + 3*sqrt(3)*I/8 + 311*I/120, -79/60 + 247*sqrt(2)*sqrt(1/2 - sqrt(2)/4)*sqrt(sqrt(2)/4 + 1/2)/30]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(b, d, dps = 2, dyadic = TRUE) })), "ERR TypeError: Ambiguity in determining the type of convolution")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(b, cc, prime = p, dyadic = TRUE) })), "ERR TypeError: Ambiguity in determining the type of convolution")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(a, b, subset = TRUE) })), "[9, 20, 5 + 9*sqrt(3), 5*sqrt(3) + 374/15, 3, 7, 3*sqrt(3), 2*sqrt(3) + 21/5]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(a, b, subset = TRUE, dyadic = FALSE) })), "[9, 20, 5 + 9*sqrt(3), 5*sqrt(3) + 374/15, 3, 7, 3*sqrt(3), 2*sqrt(3) + 21/5]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(a, b, subset = TRUE, dyadic = TRUE) })), "ERR TypeError: Ambiguity in determining the type of convolution")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(cc, d, subset = TRUE, dps = 6) })), "ERR TypeError: Ambiguity in determining the type of convolution")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(a, cc, subset = TRUE, prime = q) })), "ERR TypeError: Ambiguity in determining the type of convolution")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(list(0), list(0)) })), "[0]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(b, cc) })), "[27, 60, 67, 115, 151, 108, 87, 59, 38, 16]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(list(Rational(1,2)), list(Rational(1,2))) })), "[1/4]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(b, e) })), "[-9, 10, 239/15, 34/3, 32/3, 43/5, 113/15, 14/5]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(list(1, 0, 1), list(1, 1)) })), "[1, 1, 1, 1]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(list(Integer(0), Integer(1), Integer(0), Rational(-1, 6), Integer(0), Rational(1, 120)), list(Integer(1), Integer(0), Rational(-1, 2), Integer(0), Rational(1, 24), Integer(0))) })), "[0, 1, 0, -2/3, 0, 2/15, 0, -1/90, 0, 1/2880, 0]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(list(1, 0), list(1, 1)) })), "[1, 1, 0]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(list(0, 0), list(1, 2)) })), "[0, 0, 0]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(list(1, 0), list(1, 1), cycle = 3) })), "[1, 1, 0]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(list(1, 2, 3), list(4, 5, 6), cycle = 5) })), "[4, 13, 28, 27, 18]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(list(1, 2, 3), list(4, 5, 6), cycle = 3) })), "[31, 31, 28]")
  expect_identical(.pyrun(local({ a <- list(1, Rational(5, 3), sqrt(Integer(3)), Rational(7, 5)); b <- c(9, 5, 5, 4, 3, 2); cc <- c(3, 5, 3, 7, 8); d <- c(1422, 6572, 3213, 5552); e <- list(-1, Rational(5, 3), Rational(7, 5)); p <- 7*17*2^23 + 1; q <- 19*2^10 + 1; x <- Symbol("x"); convolution(list(1, 2, 3), list(4, 5, 6), cycle = -1) })), "ERR ValueError: The length for cyclic convolution must be non-negative")
