  expect_identical(.pyrun(local({ a <- list(1, sqrt(Integer(5)), Rational(3, 8) + 5*sym_I, 4 + 7*sym_I); b <- c(67, 51, 65, 48, 36, 79, 27); cc <- list(3 + sym_I*2/5, 5 + 9*sym_I, 7, Rational(7, 19), 13); u <- Symbol("u"); v <- Symbol("v"); w <- Symbol("w"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); intersecting_product(a, cc[1:3]) })), "[-99/5 + 10*sqrt(5) + 2*sqrt(5)*I/5 + 3021*I/40, -43 + 5*sqrt(5) + 9*sqrt(5)*I + 71*I, 245/8 + 84*I, 0]")
  expect_identical(.pyrun(local({ a <- list(1, sqrt(Integer(5)), Rational(3, 8) + 5*sym_I, 4 + 7*sym_I); b <- c(67, 51, 65, 48, 36, 79, 27); cc <- list(3 + sym_I*2/5, 5 + 9*sym_I, 7, Rational(7, 19), 13); u <- Symbol("u"); v <- Symbol("v"); w <- Symbol("w"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); intersecting_product(list(u, v, w), list(x, y)) })), "[u*x + u*y + v*x + w*x + w*y, v*y, 0, 0]")
  expect_identical(.pyrun(local({ a <- list(1, sqrt(Integer(5)), Rational(3, 8) + 5*sym_I, 4 + 7*sym_I); b <- c(67, 51, 65, 48, 36, 79, 27); cc <- list(3 + sym_I*2/5, 5 + 9*sym_I, 7, Rational(7, 19), 13); u <- Symbol("u"); v <- Symbol("v"); w <- Symbol("w"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); intersecting_product(list(u, v, w, x), list(y, z)) })), "[u*y + u*z + v*y + w*y + w*z + x*y, v*z + x*z, 0, 0]")
  expect_identical(.pyrun(local({ a <- list(1, sqrt(Integer(5)), Rational(3, 8) + 5*sym_I, 4 + 7*sym_I); b <- c(67, 51, 65, 48, 36, 79, 27); cc <- list(3 + sym_I*2/5, 5 + 9*sym_I, 7, Rational(7, 19), 13); u <- Symbol("u"); v <- Symbol("v"); w <- Symbol("w"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); intersecting_product(list(u, v), list(x, y, z)) })), "[u*x + u*y + u*z + v*x + v*z, v*y, 0, 0]")
  expect_identical(.pyrun(local({ a <- list(1, sqrt(Integer(5)), Rational(3, 8) + 5*sym_I, 4 + 7*sym_I); b <- c(67, 51, 65, 48, 36, 79, 27); cc <- list(3 + sym_I*2/5, 5 + 9*sym_I, 7, Rational(7, 19), 13); u <- Symbol("u"); v <- Symbol("v"); w <- Symbol("w"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); intersecting_product(u, Rational(8, 3)) })), "ERR TypeError: 'Symbol' object is not subscriptable")
})

test_that("convolutions: int matches SymPy", {
  expect_identical(.pyrun(local({ convolution_int(c(1), c(1)) })), "[1]")
  expect_identical(.pyrun(local({ convolution_int(c(1, 1), c(0)) })), "[0]")
  expect_identical(.pyrun(local({ convolution_int(c(1, 2, 3), c(4, 5, 6)) })), "[4, 13, 28, 27, 18]")
  expect_identical(.pyrun(local({ convolution_int(c(1), c(5, 6, 7)) })), "[5, 6, 7]")
  expect_identical(.pyrun(local({ convolution_int(c(1, 3), c(5, 6, 7)) })), "[5, 21, 25, 21]")
  expect_identical(.pyrun(local({ convolution_int(c(10, -5, 1, 3), c(-5, 6, 7)) })), "[-50, 85, 35, -44, 25, 21]")
  expect_identical(.pyrun(local({ convolution_int(c(0, 1, 0, -1), c(1, 0, -1, 0)) })), "[0, 1, 0, -2, 0, 1]")
  expect_identical(.pyrun(local({ convolution_int(c(-341, -5, 1, 3, -71, -99, 43, 87), c(5, 6, 7, 12, 345, 21, -78, -7, -89)) })), "[-1705, -2071, -2412, -4106, -118035, -9774, 25998, 2981, 5509, -34317, 19228, 38870, 5485, 1724, -4436, -7743]")
  expect_identical(.pyrun(local({ convolution_int(c(0, 0, 1), c(1, 0)) })), "[0, 0, 1]")
  expect_identical(.pyrun(local({ convolution_int(c(-1, 2), c(3, 0, 0)) })), "[-3, 6]")
  expect_identical(.pyrun(local({ convolution_int(c(123456789012345, 3), c(987654321, -2)) })), "[121932631124827861592745, -246910615061727, -6]")
})

